// THE GUARD. This runs before anything is downloaded, transcribed or answered.
//
// Your bot's username is public and searchable. This node is the only thing standing
// between a stranger and a brain that has read your lease and your invoices.
//
// The owner id is read from the environment, never written here: this workflow gets
// exported and shared, and a chat id identifies a real person's Telegram account.
const owner = String($env.BRAIN_OWNER_ID || '').trim();

if (!owner) {
  // Fail CLOSED. An empty variable must never mean "let everyone in".
  // If you are seeing this, BRAIN_OWNER_ID is not set in the container:
  //   bash setup-telegram-private.sh --stack ~/brain --status
  // Apply environment changes by recreating n8n through the Class 4 override.
  throw new Error('BRAIN_OWNER_ID is not set - refusing everyone, including you');
}

const msg = $input.first().json.message;
const fromId = String(msg?.from?.id ?? '');
const chatId = String(msg?.chat?.id ?? '');

if (fromId !== owner || chatId !== owner) {
  // Returning an empty array stops the branch: nothing downstream runs and the
  // stranger gets NO reply at all. Silence is deliberate - an error message would
  // confirm there is something live behind the username.
  console.log('refused: from=' + fromId + ' chat=' + chatId +
              ' username=@' + (msg?.from?.username || '?'));
  return [];
}

return [{
  json: {
    chatId,
    isVoice: Boolean(msg.voice),
    // Telegram gives voice notes a file_id; this is what the download node asks for.
    fileId: msg.voice?.file_id || null,
    duration: msg.voice?.duration ?? null,
    text: msg.text || null,
  },
}];

// n8n binary data may be held on disk rather than in memory, so read it through the
// helper instead of touching .binary.data.data directly.
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');

if (!buf || buf.length === 0) {
  throw new Error('the mp3 is empty - ffmpeg produced nothing, check its stderr');
}

return [{
  json: {
    audio: buf.toString('base64'),
    mp3Bytes: buf.length,
    // .first() rather than .item: every execution here handles exactly one Telegram
    // message, so there is no ambiguity to resolve - and .first() cannot fail on item
    // pairing the way .item can once the workflow has branches in it.
    chatId: $('Is this you?').first().json.chatId,
  },
}];

