const content = $input.first().json?.choices?.[0]?.message?.content;
const transcript = String(content ?? '').trim();

// An empty transcript must not be passed on as a question. Downstream it becomes an
// empty query, which retrieves whatever is nearest to nothing and gets answered
// confidently. Refuse it here instead.
const heard = transcript.length >= 2;

return [{
  json: {
    transcript,
    heard,
    chatId: $('Is this you?').first().json.chatId,
  },
}];

const r = $input.first().json;
const answered = r.answered === true;
const answer = String(r.answer ?? '').trim();
const sources = Array.isArray(r.sources) ? r.sources : [];

// Keep these THREE separate on purpose:
//   speech  - what gets read aloud. Never contains a filename.
//   text    - what appears in the message bubble, with the source for provenance.
//   answer  - the raw sentence, kept so a later change does not have to unpick a string.
//
// Hearing "the security deposit is seven thousand seven hundred dollars" is the point.
// Hearing "open paren warehouse dash lease dot em dee close paren" is not.
const text = answered && sources.length
  ? answer + '\n(' + sources.join(', ') + ')'
  : answer;

return [{
  json: {
    answered,
    answer,
    sources,
    text,
    // The refusal is passed through UNCHANGED. Class 3 says "I don't have that in your
    // documents." Do not soften it, do not append "but I could look it up". A reply
    // that apologises its way around the refusal has started guessing.
    speech: answer,
    chatId: $('Is this you?').first().json.chatId,
  },
}];

