// Concatenate the base64 FIRST, decode ONCE.
//
// Decoding each SSE frame separately and joining the resulting BYTES works by luck with
// base64 padding, and breaks the first time a frame's length is not a multiple of 3.
// It does not throw when it breaks. It produces audio that plays as static.
const body = $input.first().json.data;
if (typeof body !== 'string') {
  throw new Error('Expected raw text, got ' + typeof body +
                  ' - set the HTTP node Response Format to "text"');
}

const parts = [];
let frames = 0;
for (const raw of body.split('\n')) {
  const line = raw.trim();
  if (!line.startsWith('data:')) continue;
  const payload = line.slice(5).trim();
  if (payload === '[DONE]') break;
  try {
    const a = JSON.parse(payload)?.choices?.[0]?.delta?.audio;
    if (a?.data) { parts.push(a.data); frames++; }
  } catch (e) { /* keepalive frame, not JSON - skip it, do not throw */ }
}

const pcm = Buffer.from(parts.join(''), 'base64');
if (pcm.length === 0) {
  // An error object streams back the same way a success does. Read the raw text.
  throw new Error('no audio frames recovered from the stream');
}

return [{
  json: {
    audioFrames: frames,
    pcmBytes: pcm.length,
    seconds: +(pcm.length / 48000).toFixed(2),   // 24 kHz * 2 bytes per sample
    chatId: $('Is this you?').first().json.chatId,
  },
  binary: {
    data: {
      data: pcm.toString('base64'),
      mimeType: 'audio/L16',
      fileName: 'answer.pcm',
    },
  },
}];
